{"code":"def transform(grid):
    a=[r[:] for r in grid]
    h=len(a); w=len(a[0])
    colors={v for r in a for v in r if v}
    # special singleton color (not the main object color)
    counts={v:sum(x==v for r in a for x in r) for v in colors}
    sp=min(colors,key=lambda v: counts[v])
    pts=[(i,j) for i in range(h) for j in range(w) if a[i][j]==sp]
    main=[(i,j) for i in range(h) for j in range(w) if a[i][j] and a[i][j]!=sp]
    if not pts or not main:return a
    i,j=pts[0]; r0=min(x for x,y in main); r1=max(x for x,y in main); c0=min(y for x,y in main); c1=max(y for x,y in main)
    if j==c0 or j<c0: # ray right, as marker on left
        for y in range(c1+1,w): a[i][y]=sp
    elif j==c1 or j>c1:
        for y in range(c0-1,-1,-1): a[i][y]=sp
    elif i==r0 or i<r0:
        for x in range(r1+1,h): a[x][j]=sp
    else:
        for x in range(r0-1,-1,-1): a[x][j]=sp
    return a"}

